using System.Collections.Generic;public class Twitter{long tm;Dictionary<int,List<(long,int)>>tw=new();Dictionary<int,HashSet<int>>fo=new();public Twitter(){}public void PostTweet(int u,int id){if(!tw.ContainsKey(u))tw[u]=new();tw[u].Add((tm++,id));}public IList<int> GetNewsFeed(int u){var a=new List<(long,int)>();if(tw.ContainsKey(u))a.AddRange(tw[u]);if(fo.ContainsKey(u))foreach(int v in fo[u])if(tw.ContainsKey(v))a.AddRange(tw[v]);a.Sort((x,y)=>y.Item1.CompareTo(x.Item1));var o=new List<int>();for(int i=0;i<a.Count&&i<10;i++)o.Add(a[i].Item2);return o;}public void Follow(int a,int b){if(a==b)return;if(!fo.ContainsKey(a))fo[a]=new();fo[a].Add(b);}public void Unfollow(int a,int b){if(fo.ContainsKey(a))fo[a].Remove(b);}}
